void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)

    vec2 uv = fragCoord/iResolution.xy;

    // cor de fundo
    vec3 color = vec3(0.0);

    vec2 randomPos;

    vec2 aspectRatio = vec2(iResolution.x / iResolution.y, 1.0);

    // Número de círculos

    int numCircles = 160;

    float maxRadius = 30.0/iResolution.y; // Tamanho máximo inicial
    float growthSpeed = 0.002; // Fator de crescimento lento
    float raio = maxRadius * log(1.0 + iTime * growthSpeed / log(1.0 + growthSpeed));  


    for (int i = 0; i < numCircles; i++) {

        // Gerar posições pseudoaleatórias para os círculos

        // Gerar posições pseudoaleatórias para os círculos
        float randomX = fract(sin(float(i) * 12.9898 + 78.233) * 43758.5453);
        float randomY = fract(sin(float(i) * 93.9898 + 54.233) * 43758.5453);
        vec2 randomPos = vec2(randomX, randomY);

        // ajustar para posição da tela

        vec2 adjustedUV = (uv - randomPos) * aspectRatio;    

        // Distancia do pixel atual a posiçao do circulo

        float dist = length(adjustedUV);

        if ( dist < raio){

            color += vec3(1.0,0.3,0.2); // cor do circulo

        }
    }

    //color = clamp(color,0.0,1.0);

    fragColor = vec4(color,0.0);

}
